#"Bari_Bassic_Blues" by Joshua Haagen https://www.youtube.com/user/jzonda415/about
#originally for Saxophone Quartet and drums
#converted for Sonic Pi by Robin Newman, Aug 2021 with the composer's permission
#voiced for :dsaw synth with fxs reverb and wobble applied
#percussion parts converted to a note stream and then case statement used to select samples
#parts transposed to allow for original instrument
#use run_file "path/to/this/file" as too long for a suonic pi buffer
use_synth :dsaw
use_synth_defaults amp: 0.6
use_bpm 120
s=0.8;r=0.2 #sustain/release fractions
define :dplay do |notes,durs| #routine to extract drum "notes" and select appropriate samples to play
    notes.length.times do
      tick
      if notes.look.respond_to?(:each)
        notes.look.each do |v|
          case v
          when :Gf4
            sample :drum_cymbal_pedal,amp: 2
          when :Af4
            sample :drum_cymbal_hard,amp: 2
          when :D4
            sample :drum_bass_soft,amp: 2
          end
        end
      else
        #puts notes.look #for debugging
        case notes.look
        when :Gf4
          sample :drum_cymbal_pedal,amp: 2
        when :Af4
          sample :drum_cymbal_hard,amp: 2
        when :D4
          sample :drum_bass_soft,amp: 2
        end
      end
      sleep durs.look
    end
  end

with_fx :reverb, room: 0.6,mix: 0.6 do
with_fx :wobble,mix: 0.2 do #small amount of wobble only

